$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "#root #pausebox > div:has\(> #resumebtn\) > #fbbtn, #root #pausebox > div:has\(> #resumebtn\) > #wnbtn\{ color:var\(--tx-1\); \}"
$r1=$a1+"`n/* v28.xx (cw-pausebtn) critic on the pause box 25 (3), 42 (3), 49 (3): `"feedback and what is new are 40px quiet buttons next to 48px rows`", `"abandon is a 40px link under 48px buttons`". Now feedback, what is new and the abandon link are 48px (the button size), 16px 600 type, fill from the panel colour; abandon stays a quiet red link with no box (an older check wants that). The report box and feedback stay (Q61). */`n#root #pausebox > div:has(> #resumebtn) > #fbbtn, #root #pausebox > div:has(> #resumebtn) > #wnbtn{ min-height:var(--btn-h-sm); font-size:var(--fs-body); font-weight:600; background:var(--ui-panel); border-color:var(--ui-line-hi); }`n#root #pausebox:not(.asking) > div:has(> #resumebtn) > #abandonbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #arcendbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #charselbtn{ min-height:var(--btn-h-sm); margin-top:var(--sp-3); }"
$chk=@'
  {v:'VER',what:'pause box feedback, what is new and abandon buttons are 48px high (critic: 40px quiet buttons under 48px rows)',
   run:function(){
     var ids=['fbbtn','wnbtn','abandonbtn'];
     for(var i=0;i<ids.length;i++){
       var b=document.getElementById(ids[i]);
       if(!b) return 'SKIP: no #'+ids[i];
       var h=parseFloat(getComputedStyle(b).minHeight)||0;
       if(h<48) return '#'+ids[i]+' min-height is '+h+', not 48';
     }
     return null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='PAUSE BOX BUTTONS AT 48'
  why='Critic on the pause box (screens 25, 42, 49): feedback, what is new and abandon were 40px under 48px rows. All three are 48px now. Report box and feedback stay (Q61).'
  now='Pause box feedback, what is new and abandon buttons are 48px high.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-pausebtn.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
